+package gateway
+
+import (
+	"github.com/prometheus/client_golang/prometheus"
+
+	"internal/metrics"
+)
+
+func init() {
+	prometheus.MustRegister(metrics.HTTPClientErrors, metrics.HTTPServerErrors)
+}
+
+// RecordHTTPError increments error counters for 4xx and 5xx HTTP response status codes.
+func RecordHTTPError(statusCode int) {
+	if statusCode >= 400 && statusCode < 500 {
+		metrics.HTTPClientErrors.Inc()
+	} else if statusCode >= 500 && statusCode < 600 {
+		metrics.HTTPServerErrors.Inc()
+	}
+}
+
+// CountHTTPError is an alias for RecordHTTPError.
+func CountHTTPError(statusCode int) {
+	RecordHTTPError(statusCode)
+}
+
+// RecordResponse checks the HTTP response status code and increments error counters for 4xx and 5xx responses.
+func RecordResponse(statusCode int) {
+	RecordHTTPError(statusCode)
+}

